const QB={
 q1:[
  {k:'mean',q:'عَلَمِ الدَّوْلَةِ.',o:['رَمْزٌ لَهَا يُمَثِّلُهَا، وَيُعَبِّرُ عَنْ تَارِيخِهَا وَشَعْبِهَا','قِطْعَةُ قُمَاشٍ لِلزِّينَةِ فَقَطْ','خَرِيطَةٌ لِحُدُودِ الدَّوْلَةِ'],why:'عَلَمُ الدَّوْلَةِ رَمْزٌ يُمَثِّلُهَا، وَيُعَبِّرُ عَنْ تَارِيخِهَا وَشَعْبِهَا.'},
  {k:'fill',q:'يُعَبِّرُ عَلَمُ الدَّوْلَةِ عَنْ تَارِيخِهَا وَ...',o:['شَعْبِهَا','جِبَالِهَا','مَصَانِعِهَا'],why:'يُعَبِّرُ الْعَلَمُ عَنْ تَارِيخِ الدَّوْلَةِ وَشَعْبِهَا.'},
  {k:'tf',q:'الْمِصْرِيُّونَ الْقُدَمَاءُ مِنْ أَوَائِلِ الشُّعُوبِ الَّتِي اسْتَخْدَمَتِ الرَّايَاتِ.',a:1,why:'صَوَابٌ. اسْتَخْدَمُوا الرَّايَاتِ كَرُمُوزٍ مُهِمَّةٍ فِي حَيَاتِهِمْ.'},
  {k:'mcq',q:'اسْتَخْدَمَ الْمُلُوكُ الْمِصْرِيُّونَ الْقُدَمَاءُ الرَّايَاتِ فِي الْمَعَارِكِ لِـ...',o:['تَمْيِيزِ جُيُوشِهِمْ وَتَشْجِيعِ الْجُنُودِ','الزِّرَاعَةِ','صِنَاعَةِ الْأَدَوَاتِ'],why:'اسْتَخْدَمُوهَا لِتَمْيِيزِ جُيُوشِهِمْ وَتَشْجِيعِ الْجُنُودِ عَلَى الْقِتَالِ.'},
  {k:'fill',q:'كَانَ شِعَارُ مَمْلَكَةِ الْجَنُوبِ ...',o:['زَهْرَةَ اللُّوتَسِ','نَبَاتَ الْبَرْدِيِّ','النَّسْرَ'],why:'شِعَارُ مَمْلَكَةِ الْجَنُوبِ زَهْرَةُ اللُّوتَسِ.'},
  {k:'fix',q:'كَانَ شِعَارُ مَمْلَكَةِ الشَّمَالِ <u>زَهْرَةَ اللُّوتَسِ</u>.',o:['نَبَاتَ الْبَرْدِيِّ','النَّخْلَةَ','الشَّمْسَ'],why:'شِعَارُ مَمْلَكَةِ الشَّمَالِ نَبَاتُ الْبَرْدِيِّ، وَشِعَارُ الْجَنُوبِ زَهْرَةُ اللُّوتَسِ.'},
  {k:'odd',q:'جُدْرَانُ الْمَعَابِدِ - الْمَرَاكِبُ - الْمَسَلَّاتُ - الْقِطَارَاتُ',o:['الْقِطَارَاتُ','الْمَرَاكِبُ','الْمَسَلَّاتُ'],why:'ظَهَرَتِ الرَّايَاتُ فِي مِصْرَ الْقَدِيمَةِ عَلَى جُدْرَانِ الْمَعَابِدِ وَالْمَرَاكِبِ وَالْمَسَلَّاتِ، وَالْقِطَارَاتُ حَدِيثَةٌ.'},
  {k:'why',q:'تُغَيِّرُ الدُّوَلُ أَعْلَامَهَا أَحْيَانًا.',o:['بِسَبَبِ وُقُوعِ أَحْدَاثٍ تَارِيخِيَّةٍ مُهِمَّةٍ','لِأَنَّ الْعَلَمَ يَبْلَى','لِتَغْيِيرِ الْأَلْوَانِ فَقَطْ'],why:'تُغَيِّرُ الدُّوَلُ أَعْلَامَهَا عِنْدَ وُقُوعِ أَحْدَاثٍ تَارِيخِيَّةٍ مُهِمَّةٍ.'},
  {k:'mcq',q:'عَلَمُ الْجُمْهُورِيَّةِ الْعَرَبِيَّةِ الْمُتَّحِدَةِ كَانَ عِنْدَ اتِّحَادِ مِصْرَ مَعَ ...',o:['سُورِيَا','لِيبْيَا','السُّودَانِ'],why:'الْجُمْهُورِيَّةُ الْعَرَبِيَّةُ الْمُتَّحِدَةُ: مِصْرُ وَسُورِيَا، وَفِي عَلَمِهَا نَجْمَتَانِ.'},
  {k:'fill',q:'أَصْبَحَ عَلَمُ مِصْرَ بِشَكْلِهِ الْحَالِيِّ مُنْذُ عَامِ ...',o:['١٩٨٤','١٩٥٢','١٩٥٨'],why:'عَلَمُ مِصْرَ الْحَالِيُّ مُنْذُ عَامِ أَلْفٍ وَتِسْعِمِائَةٍ وَأَرْبَعَةٍ وَثَمَانِينَ حَتَّى الْيَوْمِ.'},
  {k:'fill',q:'يَظْهَرُ عَلَمُ مِصْرَ عَلَى شَكْلِ ...',o:['مُسْتَطِيلٍ أُفُقِيٍّ','مُرَبَّعٍ','مُثَلَّثٍ'],why:'عَلَمُ مِصْرَ مُسْتَطِيلٌ أُفُقِيٌّ مِنْ ثَلَاثَةِ أَلْوَانٍ.'},
  {k:'who',q:'اللَّوْنُ الَّذِي يَرْمُزُ إِلَى دَمِ الشُّهَدَاءِ الَّذِينَ ضَحَّوْا مِنْ أَجْلِ الْوَطَنِ.',o:['اللَّوْنُ الْأَحْمَرُ','اللَّوْنُ الْأَبْيَضُ','اللَّوْنُ الْأَسْوَدُ'],why:'الْأَحْمَرُ يَرْمُزُ إِلَى دَمِ الشُّهَدَاءِ.'},
  {k:'fill',q:'يَرْمُزُ اللَّوْنُ الْأَبْيَضُ فِي عَلَمِ مِصْرَ إِلَى ...',o:['النَّقَاءِ وَالرَّخَاءِ وَالسَّلَامِ','فَتَرَاتِ الِاسْتِعْمَارِ','دَمِ الشُّهَدَاءِ'],why:'الْأَبْيَضُ يَرْمُزُ إِلَى النَّقَاءِ وَالرَّخَاءِ وَالسَّلَامِ.'},
  {k:'tf',q:'يَرْمُزُ اللَّوْنُ الْأَسْوَدُ إِلَى فَتَرَاتِ الِاسْتِعْمَارِ الَّتِي تَعَرَّضَتْ لَهَا مِصْرُ.',a:1,why:'صَوَابٌ.'},
  {k:'tf',q:'يَرْمُزُ النَّسْرُ فِي عَلَمِ مِصْرَ إِلَى الْيَأْسِ وَالِاسْتِسْلَامِ.',a:0,why:'خَطَأٌ. النَّسْرُ رَمْزُ الْقُوَّةِ.'},
  {k:'mcq',q:'نَسْرُ عَلَمِ مِصْرَ مُسْتَوْحًى مِنْ نَسْرِ الْقَائِدِ ...',o:['صَلَاحِ الدِّينِ الْأَيُّوبِيِّ','عَمْرِو بْنِ الْعَاصِ','إِخْنَاتُونَ'],why:'النَّسْرُ مُسْتَوْحًى مِنْ نَسْرِ الْقَائِدِ صَلَاحِ الدِّينِ الْأَيُّوبِيِّ، وَهُوَ رَمْزُ الْقُوَّةِ.'},
  {k:'mcq',q:'مَاذَا كُتِبَ عَلَى قَاعِدَةِ النَّسْرِ فِي عَلَمِ مِصْرَ؟',o:['جُمْهُورِيَّةُ مِصْرَ الْعَرَبِيَّةُ','الْقَاهِرَةُ','تَحْيَا مِصْرُ'],why:'مَكْتُوبٌ عَلَى قَاعِدَتِهِ: جُمْهُورِيَّةُ مِصْرَ الْعَرَبِيَّةُ.'},
  {k:'odd',q:'الْمُنَاسَبَاتُ الرَّسْمِيَّةُ - الْوِزَارَاتُ - الْمَوَاقِعُ السِّيَاحِيَّةُ - سَلَّةُ الْمُهْمَلَاتِ',o:['سَلَّةُ الْمُهْمَلَاتِ','الْوِزَارَاتُ','الْمُنَاسَبَاتُ الرَّسْمِيَّةُ'],why:'نَرَى الْعَلَمَ فِي الْمُنَاسَبَاتِ وَالْوِزَارَاتِ وَالْمَوَاقِعِ السِّيَاحِيَّةِ، وَلَا نُلْقِيهِ أَبَدًا.'},
  {k:'mcq',q:'أَيُّ هَذِهِ السُّلُوكِيَّاتِ يَجِبُ أَنْ نَتَجَنَّبَهُ؟',o:['الْكِتَابَةُ أَوِ الرَّسْمُ عَلَى الْعَلَمِ','الْوُقُوفُ بِاحْتِرَامٍ أَثْنَاءَ تَحِيَّةِ الْعَلَمِ','رَفْعُ الْعَلَمِ بِفَخْرٍ'],why:'نَتَجَنَّبُ الْكِتَابَةَ عَلَى الْعَلَمِ، وَرَفْعَهُ مُمَزَّقًا، وَإِلْقَاءَهُ عَلَى الْأَرْضِ.'},
  {k:'why',q:'تُعْزَفُ مُوسِيقَى النَّشِيدِ الْوَطَنِيِّ فِي الْمُنَاسَبَاتِ.',o:['تَعْبِيرًا عَنِ الِانْتِمَاءِ وَالْفَخْرِ بِمِصْرَ','لِلتَّسْلِيَةِ فَقَطْ','لِإِيقَاظِ النَّاسِ'],why:'نَعْزِفُ النَّشِيدَ الْوَطَنِيَّ تَعْبِيرًا عَنِ الِانْتِمَاءِ وَالْفَخْرِ بِمِصْرَ.'}],
 q2:[
  {k:'fill',q:'تَتَكَوَّنُ الْكُرَةُ الْأَرْضِيَّةُ مِنَ الْيَابِسِ وَ...',o:['الْمَاءِ','الْجِبَالِ','الْهَوَاءِ'],why:'الْكُرَةُ الْأَرْضِيَّةُ يَابِسٌ وَمَاءٌ.'},
  {k:'mean',q:'الْقَارَّةِ.',o:['مِسَاحَةٌ وَاسِعَةٌ مِنَ الْأَرْضِ تَضُمُّ عَدَدًا مِنَ الدُّوَلِ','مِسَاحَةٌ مِنَ الْمِيَاهِ الْمَالِحَةِ','جَبَلٌ عَالٍ'],why:'الْقَارَّةُ مِسَاحَةٌ وَاسِعَةٌ مِنَ الْأَرْضِ تَضُمُّ عَدَدًا مِنَ الدُّوَلِ.'},
  {k:'mean',q:'الْمُحِيطِ.',o:['مِسَاحَةٌ شَاسِعَةٌ وَعَمِيقَةٌ مِنَ الْمِيَاهِ الْمَالِحَةِ','مَجْرًى مَائِيٌّ عَذْبٌ','بُحَيْرَةٌ صَغِيرَةٌ'],why:'الْمُحِيطُ مِسَاحَةٌ شَاسِعَةٌ وَعَمِيقَةٌ مِنَ الْمِيَاهِ الْمَالِحَةِ.'},
  {k:'why',q:'يُطْلَقُ عَلَى كَوْكَبِ الْأَرْضِ اسْمُ الْكَوْكَبِ الْمَائِيِّ.',o:['لِأَنَّ الْمِيَاهَ تُغَطِّي حَوَالَيْ ٧١٪ مِنْ مِسَاحَتِهِ','لِأَنَّ الْيَابِسَ أَكْبَرُ مِنَ الْمَاءِ','لِأَنَّهُ قَرِيبٌ مِنَ الشَّمْسِ'],why:'الْمِيَاهُ حَوَالَيْ ٧١٪، وَالْيَابِسُ نَحْوُ ٢٩٪ فَقَطْ.'},
  {k:'fill',q:'يُقَسِّمُ خَطُّ ... الْكُرَةَ الْأَرْضِيَّةَ إِلَى نِصْفَيْنِ: شَرْقِيٍّ وَغَرْبِيٍّ.',o:['جْرِينِتْشَ','الِاسْتِوَاءِ','الْحُدُودِ'],why:'خَطُّ جْرِينِتْشَ يُقَسِّمُ الْكُرَةَ الْأَرْضِيَّةَ إِلَى نِصْفٍ شَرْقِيٍّ وَنِصْفٍ غَرْبِيٍّ.'},
  {k:'mcq',q:'كَمْ يَبْلُغُ عَدَدُ قَارَّاتِ الْعَالَمِ؟',o:['سَبْعَ قَارَّاتٍ','خَمْسَ قَارَّاتٍ','عَشْرَ قَارَّاتٍ'],why:'عَدَدُ الْقَارَّاتِ سَبْعٌ، وَعَدَدُ الْمُحِيطَاتِ خَمْسَةٌ.'},
  {k:'odd',q:'إِفْرِيقْيَا - آسْيَا - أُورُوبَّا - أُسْتُرَالْيَا',o:['أُسْتُرَالْيَا','آسْيَا','إِفْرِيقْيَا'],why:'إِفْرِيقْيَا وَآسْيَا وَأُورُوبَّا قَارَّاتُ الْعَالَمِ الْقَدِيمِ، وَأُسْتُرَالْيَا مِنَ الْعَالَمِ الْجَدِيدِ.'},
  {k:'who',q:'الْقَارَّاتُ الَّتِي وَصَلَ إِلَيْهَا الْمُسْتَكْشِفُونَ فِي الْعُصُورِ الْحَدِيثَةِ.',o:['قَارَّاتُ الْعَالَمِ الْجَدِيدِ','قَارَّاتُ الْعَالَمِ الْقَدِيمِ','الْمُحِيطَاتُ'],why:'الْعَالَمُ الْجَدِيدُ: الْأَمْرِيكَتَانِ وَأُسْتُرَالْيَا وَالْقَارَّةُ الْقُطْبِيَّةُ الْجَنُوبِيَّةُ.'},
  {k:'fill',q:'أَكْبَرُ قَارَّاتِ الْعَالَمِ مِسَاحَةً هِيَ قَارَّةُ ...',o:['آسْيَا','إِفْرِيقْيَا','أُورُوبَّا'],why:'آسْيَا أَكْبَرُ الْقَارَّاتِ، وَأُسْتُرَالْيَا أَصْغَرُهَا.'},
  {k:'fix',q:'أَكْبَرُ مُحِيطَاتِ الْعَالَمِ مِسَاحَةً هُوَ الْمُحِيطُ <u>الْأَطْلَنْطِيُّ</u>.',o:['الْهَادِي','الْهِنْدِيُّ','الْمُتَجَمِّدُ الشَّمَالِيُّ'],why:'الْمُحِيطُ الْهَادِي أَكْبَرُهَا، وَالْمُتَجَمِّدُ الشَّمَالِيُّ أَصْغَرُهَا.'},
  {k:'mean',q:'الْمَوْقِعِ الْجُغْرَافِيِّ.',o:['مَوْقِعُ الْمَكَانِ بِالنِّسْبَةِ لِلْيَابِسِ وَالْمِيَاهِ','مِسَاحَةُ الدَّوْلَةِ','عَدَدُ السُّكَّانِ'],why:'الْمَوْقِعُ الْجُغْرَافِيُّ: مَوْقِعُ الْمَكَانِ بِالنِّسْبَةِ لِلْيَابِسِ وَالْمِيَاهِ.'},
  {k:'why',q:'تَتَمَيَّزُ مِصْرُ بِمَوْقِعٍ جُغْرَافِيٍّ فَرِيدٍ.',o:['لِأَنَّهَا تَقَعُ فِي قَلْبِ قَارَّاتِ الْعَالَمِ الْقَدِيمِ','لِأَنَّهَا أَكْبَرُ دَوْلَةٍ فِي الْعَالَمِ','لِأَنَّهَا فِي قَارَّةِ أُسْتُرَالْيَا'],why:'تَقَعُ مِصْرُ فِي قَلْبِ الْعَالَمِ الْقَدِيمِ، فِي الرُّكْنِ الشَّمَالِيِّ الشَّرْقِيِّ مِنْ إِفْرِيقْيَا.'},
  {k:'res',q:'مَوْقِعِ مِصْرَ عَلَى الْبَحْرَيْنِ الْأَحْمَرِ وَالْمُتَوَسِّطِ.',o:['قِيَامُ مِصْرَ بِدَوْرٍ مُهِمٍّ فِي التِّجَارَةِ الدَّوْلِيَّةِ','قِلَّةُ التِّجَارَةِ','بُعْدُ مِصْرَ عَنِ الْعَالَمِ'],why:'لِأَنَّهَا تُطِلُّ عَلَى الْبَحْرَيْنِ، تَقُومُ مِصْرُ بِدَوْرٍ مُهِمٍّ فِي التِّجَارَةِ الدَّوْلِيَّةِ.'},
  {k:'mean',q:'الْحُدُودِ الدَّوْلِيَّةِ.',o:['الْخُطُوطُ الْفَاصِلَةُ بَيْنَ كُلِّ دَوْلَةٍ وَغَيْرِهَا مِنَ الدُّوَلِ','الْخُطُوطُ بَيْنَ الْمُحَافَظَاتِ','شَوَاطِئُ الْبِحَارِ'],why:'الْحُدُودُ الدَّوْلِيَّةُ تَفْصِلُ بَيْنَ كُلِّ دَوْلَةٍ وَغَيْرِهَا.'},
  {k:'tf',q:'يَحُدُّ مِصْرَ مِنَ الشَّمَالِ الشَّرْقِيِّ دَوْلَةُ لِيبْيَا.',a:0,why:'خَطَأٌ. يَحُدُّهَا مِنَ الشَّمَالِ الشَّرْقِيِّ دَوْلَةُ فِلَسْطِينَ، وَلِيبْيَا غَرْبًا.'},
  {k:'fill',q:'يَحُدُّ مِصْرَ جَنُوبًا دَوْلَةُ ...',o:['السُّودَانِ','لِيبْيَا','فِلَسْطِينَ'],why:'السُّودَانُ جَنُوبًا، وَلِيبْيَا غَرْبًا.'},
  {k:'mcq',q:'مَاذَا يَحُدُّ مِصْرَ شَمَالًا؟',o:['الْبَحْرُ الْمُتَوَسِّطُ','الْبَحْرُ الْأَحْمَرُ','دَوْلَةُ السُّودَانِ'],why:'يَحُدُّهَا شَمَالًا الْبَحْرُ الْمُتَوَسِّطُ، وَشَرْقًا خَلِيجُ الْعَقَبَةِ وَالْبَحْرُ الْأَحْمَرُ.'},
  {k:'tf',q:'تَبْلُغُ مِسَاحَةُ مِصْرَ حَوَالَيْ مِلْيُونِ كِيلُومِتْرٍ مُرَبَّعٍ.',a:1,why:'صَوَابٌ.'},
  {k:'tf',q:'مِنْ مَهَامِّ الْجَيْشِ الْمِصْرِيِّ مَنْعُ تَسَلُّلِ الْأَفْرَادِ.',a:1,why:'صَوَابٌ. وَيَحْمِي الْحُدُودَ، وَيَمْنَعُ تَهْرِيبَ الْأَسْلِحَةِ وَالْمُخَدِّرَاتِ.'},
  {k:'dl',q:'يَبْذُلُ الْجَيْشُ الْمِصْرِيُّ جُهْدًا كَبِيرًا لِحِمَايَةِ حُدُودِ مِصْرَ.',o:['يَمْنَعُ تَسَلُّلَ الْأَفْرَادِ وَتَهْرِيبَ الْأَسْلِحَةِ وَالْمُخَدِّرَاتِ','يَزْرَعُ الْحُقُولَ','يَبْنِي الْمَدَارِسَ'],why:'الْجَيْشُ يَحْمِي الْحُدُودَ وَيَمْنَعُ التَّسَلُّلَ وَالتَّهْرِيبَ.'},
  {k:'mcq',q:'بِمَاذَا يَمْتَازُ الْجُنْدِيُّ الْمِصْرِيُّ؟',o:['بِالْبَسَالَةِ وَالشَّجَاعَةِ','بِالْخَوْفِ','بِالْكَسَلِ'],why:'يَمْتَازُ الْجُنْدِيُّ الْمِصْرِيُّ بِالْبَسَالَةِ وَالشَّجَاعَةِ.'}],
 q3:[
  {k:'mean',q:'التَّضَارِيسِ.',o:['أَشْكَالُ سَطْحِ الْأَرْضِ الْمُخْتَلِفَةُ بَيْنَ مُرْتَفِعَاتٍ وَمُنْخَفِضَاتٍ','الْمَوَارِدُ الطَّبِيعِيَّةُ','حُدُودُ الدَّوْلَةِ'],why:'التَّضَارِيسُ: أَشْكَالُ سَطْحِ الْأَرْضِ بَيْنَ مُرْتَفِعَاتٍ وَمُنْخَفِضَاتٍ.'},
  {k:'why',q:'تَخْتَلِفُ الْأَلْوَانُ عَلَى خَرِيطَةِ مُسْتَوَيَاتِ ارْتِفَاعِ سَطْحِ مِصْرَ.',o:['بِسَبَبِ تَنَوُّعِ التَّضَارِيسِ وَتَدَرُّجِهَا حَسَبَ الِارْتِفَاعِ','لِتَزْيِينِ الْخَرِيطَةِ','بِسَبَبِ اخْتِلَافِ الْمُحَافَظَاتِ'],why:'الْأَلْوَانُ تُبَيِّنُ اخْتِلَافَ ارْتِفَاعِ الْأَرْضِ وَتَدَرُّجَهُ.'},
  {k:'who',q:'أَرْضٌ شَدِيدَةُ الِارْتِفَاعِ، لَهَا قِمَّةٌ تَزِيدُ عَلَى أَلْفِ مِتْرٍ، وَجَوَانِبُهَا شَدِيدَةُ الِانْحِدَارِ.',o:['الْجَبَلُ','التَّلُّ','الْهَضَبَةُ'],why:'هَذَا تَعْرِيفُ الْجَبَلِ.'},
  {k:'who',q:'أَرْضٌ مُرْتَفِعَةٌ لَهَا قِمَّةٌ يَقِلُّ ارْتِفَاعُهَا عَنْ أَلْفِ مِتْرٍ.',o:['التَّلُّ','الْجَبَلُ','الْمُنْخَفَضُ'],why:'التَّلُّ أَقَلُّ مِنْ أَلْفِ مِتْرٍ، مِثْلُ تِلَالِ الْمُقَطَّمِ.'},
  {k:'who',q:'مِسَاحَةٌ وَاسِعَةٌ مِنَ الْأَرْضِ الْمُرْتَفِعَةِ مُسْتَوِيَةُ السَّطْحِ أَوْ شِبْهُ مُسْتَوِيَةٍ.',o:['الْهَضَبَةُ','السَّهْلُ السَّاحِلِيُّ','الْجَزِيرَةُ'],why:'الْهَضَبَةُ، مِثْلُ هَضَبَةِ الْجِلْفِ الْكَبِيرِ.'},
  {k:'fill',q:'أَعْلَى قِمَّةٍ جَبَلِيَّةٍ فِي مِصْرَ هِيَ جَبَلُ ...',o:['سَانْتْ كَاتْرِينَ','الْمُقَطَّمِ','عُلْبَةَ'],why:'جَبَلُ سَانْتْ كَاتْرِينَ فِي جَنُوبِ سَيْنَاءَ أَعْلَى قِمَّةٍ جَبَلِيَّةٍ فِي مِصْرَ.'},
  {k:'mcq',q:'تَقَعُ هَضَبَةُ الْجِلْفِ الْكَبِيرِ فِي ...',o:['جَنُوبِ غَرْبِ مِصْرَ','شَمَالِ شَرْقِ مِصْرَ','وَسَطِ الدِّلْتَا'],why:'هَضَبَةُ الْجِلْفِ الْكَبِيرِ فِي جَنُوبِ غَرْبِ مِصْرَ.'},
  {k:'dl',q:'اسْتَفَادَ الْمِصْرِيُّونَ الْقُدَمَاءُ مِنَ الْجِبَالِ وَالْهِضَابِ.',o:['حَصَلُوا مِنْهَا عَلَى الْمَعَادِنِ وَالصُّخُورِ لِبِنَاءِ الْمَعَابِدِ وَالْأَهْرَامَاتِ','زَرَعُوا فَوْقَهَا الْقَمْحَ','صَادُوا مِنْهَا الْأَسْمَاكَ'],why:'أَخَذُوا مِنْهَا الْمَعَادِنَ لِأَدَوَاتِهِمْ، وَالْأَحْجَارَ لِلْمَعَابِدِ وَالْأَهْرَامَاتِ وَالتَّمَاثِيلِ.'},
  {k:'who',q:'مِسَاحَةٌ مِنَ الْأَرْضِ مُسْتَوِيَةٌ وَقَلِيلَةُ الِارْتِفَاعِ، وَتَتَكَوَّنُ مِنْ رَوَاسِبِ الْأَنْهَارِ.',o:['السُّهُولُ الْفَيْضِيَّةُ','السُّهُولُ السَّاحِلِيَّةُ','الْهِضَابُ'],why:'السُّهُولُ الْفَيْضِيَّةُ، مِثْلُ السُّهُولِ عَلَى جَانِبَيْ نَهْرِ النِّيلِ.'},
  {k:'rel',q:'السُّهُولِ الْفَيْضِيَّةِ وَالزِّرَاعَةِ.',o:['تُرْبَتُهَا خِصْبَةٌ صَالِحَةٌ لِلزِّرَاعَةِ','لَا تَصْلُحُ لِلزِّرَاعَةِ','لَا عَلَاقَةَ بَيْنَهُمَا'],why:'السُّهُولُ الْفَيْضِيَّةُ تَتَمَيَّزُ بِتُرْبَتِهَا الْخِصْبَةِ الصَّالِحَةِ لِلزِّرَاعَةِ.'},
  {k:'why',q:'يَتَّسِمُ سَاحِلُ الْبَحْرِ الْأَحْمَرِ بِالضِّيقِ.',o:['بِسَبَبِ اقْتِرَابِ الْجِبَالِ مِنْهُ','بِسَبَبِ كَثْرَةِ الْأَنْهَارِ','لِأَنَّهُ بَحْرٌ عَذْبٌ'],why:'سَاحِلُ الْبَحْرِ الْأَحْمَرِ ضَيِّقٌ لِاقْتِرَابِ الْجِبَالِ مِنْهُ، وَسَاحِلُ الْمُتَوَسِّطِ وَاسِعٌ.'},
  {k:'res',q:'جَمَالِ شَوَاطِئِ مِصْرَ وَمَنَاظِرِهَا الطَّبِيعِيَّةِ.',o:['تَجْذِبُ السَّائِحِينَ، فَتُوَفِّرُ الْمَزِيدَ مِنْ فُرَصِ الْعَمَلِ','تُسَبِّبُ التَّلَوُّثَ','تَمْنَعُ الزِّرَاعَةَ'],why:'الشَّوَاطِئُ الْجَمِيلَةُ تَجْذِبُ السَّائِحِينَ، وَتُوَفِّرُ فُرَصَ عَمَلٍ.'},
  {k:'who',q:'أَرْضٌ مُنْخَفِضَةٌ عَمَّا حَوْلَهَا.',o:['الْمُنْخَفَضُ','الْجَبَلُ','شِبْهُ الْجَزِيرَةِ'],why:'الْمُنْخَفَضُ، مِثْلُ مُنْخَفَضِ الْفَيُّومِ.'},
  {k:'who',q:'مِسَاحَةٌ مِنَ الْيَابِسِ تُحِيطُ بِهَا الْمِيَاهُ مِنْ ثَلَاثِ جِهَاتٍ.',o:['شِبْهُ الْجَزِيرَةِ','الْجَزِيرَةُ','الْبُحَيْرَةُ'],why:'شِبْهُ الْجَزِيرَةِ، مِثْلُ شِبْهِ جَزِيرَةِ سَيْنَاءَ.'},
  {k:'fill',q:'جَزِيرَةُ شَدْوَانَ تَقَعُ فِي الْبَحْرِ ...',o:['الْأَحْمَرِ','الْمُتَوَسِّطِ','الْمَيِّتِ'],why:'جَزِيرَةُ شَدْوَانَ بِالْبَحْرِ الْأَحْمَرِ، تُحِيطُ بِهَا الْمِيَاهُ مِنْ جَمِيعِ الْجِهَاتِ.'},
  {k:'mean',q:'الْبَحْرِ.',o:['مِسَاحَةٌ وَاسِعَةٌ مِنَ الْمِيَاهِ الْمَالِحَةِ أَصْغَرُ مِنَ الْمُحِيطِ','مَجْرًى مَائِيٌّ عَذْبٌ','أَرْضٌ مُنْخَفِضَةٌ'],why:'الْبَحْرُ مَالِحٌ وَأَصْغَرُ مِنَ الْمُحِيطِ.'},
  {k:'fill',q:'مِنْ بُحَيْرَاتِ مِصْرَ الشَّمَالِيَّةِ الْمَالِحَةِ بُحَيْرَةُ ...',o:['الْمَنْزَلَةِ','نَاصِرٍ','قَارُونَ'],why:'الْبَرْدَوِيلُ وَالْمَنْزَلَةُ بُحَيْرَتَانِ مَالِحَتَانِ عَلَى الْبَحْرِ الْمُتَوَسِّطِ.'},
  {k:'tf',q:'بُحَيْرَةُ نَاصِرٍ بُحَيْرَةٌ عَذْبَةٌ خَلْفَ السَّدِّ الْعَالِي جَنُوبَ مِصْرَ.',a:1,why:'صَوَابٌ.'},
  {k:'fill',q:'يَصُبُّ نَهْرُ النِّيلِ فِي الْبَحْرِ ...',o:['الْمُتَوَسِّطِ','الْأَحْمَرِ','الْعَرَبِ'],why:'يَجْرِي النِّيلُ مِنَ الْجَنُوبِ إِلَى الشَّمَالِ، وَيَصُبُّ فِي الْبَحْرِ الْمُتَوَسِّطِ.'},
  {k:'mcq',q:'مَا الِاخْتِلَافُ بَيْنَ النَّهْرِ وَالْبَحْرِ؟',o:['النَّهْرُ مَجْرًى عَذْبٌ، وَالْبَحْرُ مِيَاهٌ مَالِحَةٌ','النَّهْرُ مَالِحٌ، وَالْبَحْرُ عَذْبٌ','لَا يَوْجَدُ اخْتِلَافٌ'],why:'النَّهْرُ مَجْرًى مَائِيٌّ عَذْبٌ، وَالْبَحْرُ مِسَاحَةٌ وَاسِعَةٌ مِنَ الْمِيَاهِ الْمَالِحَةِ.'}],
 q4:[
  {k:'mean',q:'الْمَوَارِدِ الطَّبِيعِيَّةِ.',o:['كُلُّ مَا وَهَبَهُ اللَّهُ لَنَا فِي الطَّبِيعَةِ دُونَ تَدَخُّلٍ مِنَ الْإِنْسَانِ','مَا يَصْنَعُهُ الْإِنْسَانُ فِي الْمَصَانِعِ','الْأَمْوَالُ فِي الْبُنُوكِ'],why:'الْمَوَارِدُ الطَّبِيعِيَّةُ مِثْلُ الْمِيَاهِ وَالْهَوَاءِ وَالتُّرْبَةِ وَالْمَعَادِنِ.'},
  {k:'fill',q:'تَنْقَسِمُ الْمَوَارِدُ الطَّبِيعِيَّةُ إِلَى مُتَجَدِّدَةٍ وَ...',o:['غَيْرِ مُتَجَدِّدَةٍ','بَشَرِيَّةٍ','صِنَاعِيَّةٍ'],why:'الْمَوَارِدُ الطَّبِيعِيَّةُ: مُتَجَدِّدَةٌ وَغَيْرُ مُتَجَدِّدَةٍ.'},
  {k:'who',q:'أَحَدُ الْمَوَارِدِ الطَّبِيعِيَّةِ، وَيُسْتَخْدَمُ لِلشُّرْبِ وَالرَّيِّ.',o:['الْمَاءُ الْعَذْبُ','الْبِتْرُولُ','الْفَحْمُ'],why:'الْمَاءُ الْعَذْبُ لِلشُّرْبِ وَالرَّيِّ.'},
  {k:'mcq',q:'نَسْتَخْدِمُ الشَّمْسَ وَالرِّيَاحَ فِي ...',o:['إِنْتَاجِ الطَّاقَةِ النَّظِيفَةِ','الشُّرْبِ','بِنَاءِ الْمَنَازِلِ'],why:'الشَّمْسُ وَالرِّيَاحُ لِإِنْتَاجِ الطَّاقَةِ النَّظِيفَةِ.'},
  {k:'why',q:'أَهَمِّيَّةُ الْمَعَادِنِ.',o:['لِأَنَّهَا تَقُومُ عَلَيْهَا الصِّنَاعَةُ','لِأَنَّهَا تُرْوَى بِهَا الْحُقُولُ','لِأَنَّهَا تُنَقِّي الْهَوَاءَ'],why:'الْمَعَادِنُ تَقُومُ عَلَيْهَا الصِّنَاعَةُ.'},
  {k:'why',q:'أَهَمِّيَّةُ الْبِتْرُولِ وَالْغَازِ الطَّبِيعِيِّ.',o:['لِإِنْتَاجِ الطَّاقَةِ','لِلشُّرْبِ','لِلزِّرَاعَةِ'],why:'الْبِتْرُولُ وَالْغَازُ الطَّبِيعِيُّ لِإِنْتَاجِ الطَّاقَةِ.'},
  {k:'who',q:'مَوَارِدُ تَتَجَدَّدُ بِاسْتِمْرَارٍ وَغَيْرُ قَابِلَةٍ لِلنَّفَادِ.',o:['الْمَوَارِدُ الْمُتَجَدِّدَةُ','الْمَوَارِدُ غَيْرُ الْمُتَجَدِّدَةِ','الْمَوَارِدُ الْبَشَرِيَّةُ'],why:'مِثْلُ الْمِيَاهِ وَطَاقَةِ الشَّمْسِ وَالرِّيَاحِ.'},
  {k:'odd',q:'الْفَحْمُ - الْبِتْرُولُ - الْمَعَادِنُ - الرِّيَاحُ',o:['الرِّيَاحُ','الْفَحْمُ','الْبِتْرُولُ'],why:'الرِّيَاحُ مَوْرِدٌ مُتَجَدِّدٌ، وَالْبَاقِي غَيْرُ مُتَجَدِّدٍ.'},
  {k:'why',q:'تَتَعَرَّضُ الْمَوَارِدُ غَيْرُ الْمُتَجَدِّدَةِ لِلنَّفَادِ.',o:['بِسَبَبِ زِيَادَةِ اسْتِهْلَاكِنَا لَهَا','لِأَنَّهَا تَتَجَدَّدُ بِاسْتِمْرَارٍ','لِأَنَّهَا كَثِيرَةٌ جِدًّا'],why:'هِيَ مَحْدُودَةٌ، وَتَسْتَغْرِقُ آلَافَ السِّنِينَ لِتَتَكَوَّنَ، فَتَنْفَدُ بِزِيَادَةِ الِاسْتِهْلَاكِ.'},
  {k:'tf',q:'مِنْ فَوَائِدِ الْمَوَارِدِ الطَّبِيعِيَّةِ تَوْفِيرُ الْغِذَاءِ.',a:1,why:'صَوَابٌ. وَتُوَفِّرُ الْمَسْكَنَ وَالْمَلْبَسَ وَالْمَوَادَّ الْخَامَ، وَهِيَ مَصْدَرٌ لِلدَّخْلِ.'},
  {k:'mean',q:'الْحَيَاةِ الْمُسْتَدَامَةِ.',o:['اسْتِخْدَامُ الْمَوَارِدِ الطَّبِيعِيَّةِ بِحِكْمَةٍ حَتَّى تَكْفِيَ الْجَمِيعَ وَتَبْقَى لِلْأَجْيَالِ الْقَادِمَةِ','اسْتِهْلَاكُ كُلِّ الْمَوَارِدِ الْآنَ','الْعَيْشُ فِي الصَّحْرَاءِ'],why:'الْحَيَاةُ الْمُسْتَدَامَةُ: نَسْتَخْدِمُ الْمَوَارِدَ بِحِكْمَةٍ لِنَا وَلِلْأَجْيَالِ الْقَادِمَةِ.'},
  {k:'mcq',q:'مَا حَلُّ مُشْكِلَةِ تَلَوُّثِ التُّرْبَةِ؟',o:['اسْتِخْدَامُ السَّمَادِ الْعُضْوِيِّ','زِيَادَةُ الْمُبِيدَاتِ الْحَشَرِيَّةِ','إِلْقَاءُ الْقُمَامَةِ فِيهَا'],why:'تَتَلَوَّثُ التُّرْبَةُ بِالْمُبِيدَاتِ وَالْأَسْمِدَةِ الْكِيمْيَائِيَّةِ، وَالْحَلُّ السَّمَادُ الْعُضْوِيُّ.'},
  {k:'why',q:'أَطْلَقَتِ الدَّوْلَةُ مُبَادَرَةَ اتَّحَضَّرْ لِلْأَخْضَرْ.',o:['لِلْحِفَاظِ عَلَى الْحَيَاةِ الْمُسْتَدَامَةِ وَالْبِيئَةِ النَّظِيفَةِ','لِبِنَاءِ الْمَصَانِعِ','لِزِيَادَةِ الِاسْتِهْلَاكِ'],why:'وَلِحَثِّ الْمُوَاطِنِينَ عَلَى الْمُشَارَكَةِ فِي الْحِفَاظِ عَلَى الْبِيئَةِ.'},
  {k:'why',q:'زِرَاعَةُ الْأَشْجَارِ.',o:['لِتَنْقِيَةِ الْهَوَاءِ مِنَ التَّلَوُّثِ','لِإِهْدَارِ الْمِيَاهِ','لِتَلْوِيثِ التُّرْبَةِ'],why:'الْأَشْجَارُ تُنَقِّي الْهَوَاءَ مِنَ التَّلَوُّثِ.'},
  {k:'mcq',q:'أَيُّ سُلُوكٍ يُهْدِرُ الْمَوَارِدَ؟',o:['تَرْكُ صُنْبُورِ الْمِيَاهِ مَفْتُوحًا دُونَ حَاجَةٍ','إِطْفَاءُ الْمَصَابِيحِ عِنْدَ مُغَادَرَةِ الْغُرْفَةِ','زِرَاعَةُ الْأَشْجَارِ'],why:'تَرْكُ الصُّنْبُورِ مَفْتُوحًا يُهْدِرُ الْمِيَاهَ.'},
  {k:'why',q:'يُعَدُّ الْمِصْرِيُّونَ الثَّرْوَةَ الْحَقِيقِيَّةَ لِمِصْرَ.',o:['لِأَنَّهُمْ مَنْ يَصْنَعُ مُسْتَقْبَلَنَا','لِأَنَّهُمْ يَمْلِكُونَ الذَّهَبَ','لِأَنَّهُمْ كَثِيرُو السَّفَرِ'],why:'الْمِصْرِيُّونَ الْكَنْزُ الثَّمِينُ لِأَنَّهُمْ يَصْنَعُونَ الْمُسْتَقْبَلَ.'},
  {k:'tf',q:'يَرْجِعُ سَبَبُ تَقَدُّمِ الْيَابَانِ إِلَى كَثْرَةِ ثَرَوَاتِهَا الطَّبِيعِيَّةِ.',a:0,why:'خَطَأٌ. تَقَدَّمَتِ الْيَابَانُ بِفَضْلِ قُدُرَاتِ أَبْنَائِهَا الْمُتَعَلِّمِينَ وَالْمُبْدِعِينَ.'},
  {k:'who',q:'لُقِّبَ بِعَمِيدِ الْأَدَبِ الْعَرَبِيِّ، وَمِنْ أَشْهَرِ كُتُبِهِ الْأَيَّامُ.',o:['الدُّكْتُورُ طَه حُسَيْن','الدُّكْتُورُ أَحْمَد زُوَيْل','الدُّكْتُورُ جَمَال حَمْدَان'],why:'الدُّكْتُورُ طَه حُسَيْن فَقَدَ بَصَرَهُ صَغِيرًا وَلَمْ يَسْتَسْلِمْ.'},
  {k:'who',q:'أَوَّلُ عَالِمَةٍ مِصْرِيَّةٍ تَحْصُلُ عَلَى الدُّكْتُورَاه فِي مَجَالِ الطَّاقَةِ النَّوَوِيَّةِ.',o:['الدُّكْتُورَةُ سَمِيرَة مُوسَى','الدُّكْتُورُ مُصْطَفَى السَّيِّد','الدُّكْتُورُ طَه حُسَيْن'],why:'الدُّكْتُورَةُ سَمِيرَة مُوسَى أَسْهَمَتْ فِي تَأْسِيسِ هَيْئَةِ الطَّاقَةِ الذَّرِّيَّةِ.'},
  {k:'who',q:'عَالِمٌ مِصْرِيٌّ حَصَلَ عَلَى جَائِزَةِ نُوبِل فِي الْكِيمْيَاءِ لِاخْتِرَاعِهِ تِقْنِيَةَ الْفِيمْتُو ثَانِيَة.',o:['الدُّكْتُورُ أَحْمَد زُوَيْل','الدُّكْتُورُ جَمَال حَمْدَان','الدُّكْتُورُ مُصْطَفَى السَّيِّد'],why:'الدُّكْتُورُ أَحْمَد زُوَيْل.'},
  {k:'who',q:'عَالِمُ الْجُغْرَافْيَا صَاحِبُ مَوْسُوعَةِ شَخْصِيَّةِ مِصْرَ.',o:['الدُّكْتُورُ جَمَال حَمْدَان','الدُّكْتُورُ أَحْمَد زُوَيْل','الدُّكْتُورَةُ سَمِيرَة مُوسَى'],why:'الدُّكْتُورُ جَمَال حَمْدَان تَنَاوَلَ فِيهَا تَارِيخَ مِصْرَ وَجُغْرَافِيَّتَهَا.'},
  {k:'mcq',q:'اسْتَخْدَمَ الدُّكْتُورُ مُصْطَفَى السَّيِّد جُزَيْئَاتِ الذَّهَبِ الصَّغِيرَةَ فِي ...',o:['عِلَاجِ مَرَضِ السَّرَطَانِ','صِنَاعَةِ الْحُلِيِّ','بِنَاءِ الْمَنَازِلِ'],why:'تَقْتُلُ الْخَلَايَا السَّرَطَانِيَّةَ دُونَ أَنْ تُؤْذِيَ الْخَلَايَا السَّلِيمَةَ.'}],
 q5:[
  {k:'mean',q:'الْمَعْلَمِ التَّارِيخِيِّ.',o:['مَكَانٌ أَوْ مَبْنًى قَدِيمٌ لَهُ قِيمَةٌ تَارِيخِيَّةٌ وَثَقَافِيَّةٌ، وَمَا زَالَ مَوْجُودًا حَتَّى الْيَوْمِ','مَبْنًى حَدِيثٌ بُنِيَ أَمْسِ','حَدِيقَةٌ عَامَّةٌ'],why:'الْمَعْلَمُ التَّارِيخِيُّ قَدِيمٌ، لَهُ قِيمَةٌ، وَمَا زَالَ قَائِمًا.'},
  {k:'why',q:'تَهْتَمُّ مُعْظَمُ دُوَلِ الْعَالَمِ بِدِرَاسَةِ التَّارِيخِ الْمِصْرِيِّ الْقَدِيمِ.',o:['لِأَنَّ الْحَضَارَةَ الْمِصْرِيَّةَ مِنْ أَعْظَمِ الْحَضَارَاتِ فِي التَّارِيخِ','لِأَنَّ مِصْرَ دَوْلَةٌ صَغِيرَةٌ','لِأَنَّ مِصْرَ بِلَا آثَارٍ'],why:'أَبْدَعَ الْمِصْرِيُّونَ فِي الْفَنِّ وَالْعِمَارَةِ، وَتَرَكُوا تُرَاثًا لَا يُقَدَّرُ بِثَمَنٍ.'},
  {k:'who',q:'أَوَّلُ بِنَاءٍ حَجَرِيٍّ ضَخْمٍ فِي التَّارِيخِ، يَتَكَوَّنُ مِنْ مَصَاطِبَ مُتَدَرِّجَةٍ.',o:['هَرَمُ زُوسَرَ الْمُدَرَّجُ','بُرْجُ الْقَاهِرَةِ','الْمَسْرَحُ الرُّومَانِيُّ'],why:'هَرَمُ زُوسَرَ الْمُدَرَّجُ فِي سَقَّارَةَ بِالْجِيزَةِ.'},
  {k:'fill',q:'مِنَ الْمَعَالِمِ التَّارِيخِيَّةِ بِمَدِينَةِ الْأُقْصُرِ ...',o:['مَعَابِدُ الْكَرْنَكِ','الْمَسْرَحُ الرُّومَانِيُّ','دَيْرُ سَانْتْ كَاتْرِينَ'],why:'مَعَابِدُ الْكَرْنَكِ فِي مَدِينَةِ طِيبَةَ، الْأُقْصُرِ حَالِيًّا.'},
  {k:'fill',q:'يَقَعُ دَيْرُ سَانْتْ كَاتْرِينَ فِي جَنُوبِ ...',o:['سَيْنَاءَ','الْجِيزَةِ','الْإِسْكَنْدَرِيَّةِ'],why:'دَيْرُ سَانْتْ كَاتْرِينَ مِنْ أَقْدَمِ الْأَدْيِرَةِ فِي الْعَالَمِ.'},
  {k:'fix',q:'يَقَعُ الْمَسْرَحُ الرُّومَانِيُّ فِي مَدِينَةِ <u>الْأُقْصُرِ</u>.',o:['الْإِسْكَنْدَرِيَّةِ','الْقَاهِرَةِ','أَسْوَانَ'],why:'الْمَسْرَحُ الرُّومَانِيُّ فِي الْإِسْكَنْدَرِيَّةِ، وَيَعْكِسُ ازْدِهَارَ الْحَيَاةِ الثَّقَافِيَّةِ وَالْفَنِّيَّةِ فِيهَا قَدِيمًا.'},
  {k:'why',q:'سُمِّيَ الْجَامِعُ الْأَزْهَرُ بِهَذَا الِاسْمِ.',o:['نِسْبَةً إِلَى السَّيِّدَةِ فَاطِمَةَ الزَّهْرَاءِ ابْنَةِ الرَّسُولِ ﷺ','لِأَنَّهُ مَبْنِيٌّ مِنَ الزُّهُورِ','لِأَنَّهُ فِي حَدِيقَةٍ'],why:'سُمِّيَ بِالْأَزْهَرِ نِسْبَةً إِلَى السَّيِّدَةِ فَاطِمَةَ الزَّهْرَاءِ.'},
  {k:'mcq',q:'بُرْجُ الْقَاهِرَةِ عَلَى شَكْلِ ...',o:['زَهْرَةِ اللُّوتَسِ','نَبَاتِ الْبَرْدِيِّ','النَّخْلَةِ'],why:'بُرْجُ الْقَاهِرَةِ أُسْطُوَانِيٌّ عَلَى شَكْلِ زَهْرَةِ اللُّوتَسِ.'},
  {k:'who',q:'الرَّئِيسُ الْمِصْرِيُّ الَّذِي بُنِيَ فِي عَهْدِهِ بُرْجُ الْقَاهِرَةِ.',o:['جَمَال عَبْدُ النَّاصِرِ','صَلَاحُ الدِّينِ الْأَيُّوبِيُّ','إِخْنَاتُونُ'],why:'بُنِيَ بُرْجُ الْقَاهِرَةِ فِي عَهْدِ الرَّئِيسِ جَمَال عَبْدِ النَّاصِرِ.'},
  {k:'who',q:'الْمَلِكُ الْفِرْعَوْنِيُّ الْمُلَقَّبُ بِالْمَلِكِ الذَّهَبِيِّ.',o:['تُوت عَنْخ آمُون','زُوسَرُ','إِخْنَاتُونُ'],why:'تُوت عَنْخ آمُون، وَنَزُورُ قَاعَةَ مُقْتَنَيَاتِهِ افْتِرَاضِيًّا.'},
  {k:'why',q:'تُعَدُّ الْمَعَالِمُ التَّارِيخِيَّةُ ثَرْوَةً قَوْمِيَّةً.',o:['لِأَنَّهَا تُعَلِّمُنَا تَارِيخَ أَجْدَادِنَا، وَتُوَفِّرُ وَظَائِفَ مِنْ خِلَالِ السِّيَاحَةِ','لِأَنَّهَا تُبَاعُ لِلسَّائِحِينَ','لِأَنَّهَا مَبَانٍ حَدِيثَةٌ'],why:'وَتَجْعَلُنَا نَشْعُرُ بِالِانْتِمَاءِ إِلَى وَطَنِنَا الْعَظِيمِ مِصْرَ.'},
  {k:'rel',q:'الْمَعَالِمِ التَّارِيخِيَّةِ وَالِاقْتِصَادِ الْمِصْرِيِّ.',o:['تُوَفِّرُ وَظَائِفَ مِنْ خِلَالِ السِّيَاحَةِ فَتَدْعَمُ الِاقْتِصَادَ','تُسَبِّبُ الْبَطَالَةَ','لَا عَلَاقَةَ بَيْنَهُمَا'],why:'السِّيَاحَةُ تُوَفِّرُ وَظَائِفَ لِلْمِصْرِيِّينَ وَتَدْعَمُ الِاقْتِصَادَ.'},
  {k:'tf',q:'يُمْكِنُ أَنْ نَكْتُبَ أَسْمَاءَنَا عَلَى الْآثَارِ عِنْدَ زِيَارَتِهَا لِتَخْلِيدِ الذِّكْرَى.',a:0,why:'خَطَأٌ. الْكِتَابَةُ عَلَى الْآثَارِ تُؤَدِّي إِلَى تَلَفِهَا.'},
  {k:'tf',q:'حِمَايَةُ الْآثَارِ مَسْؤُولِيَّةُ الْجَمِيعِ.',a:1,why:'صَوَابٌ. الْحِفَاظُ عَلَيْهَا وَاجِبٌ عَلَى كُلِّ مِصْرِيٍّ.'},
  {k:'mcq',q:'كَيْفَ نُعَامِلُ السَّائِحِينَ؟',o:['بِأَدَبٍ وَابْتِسَامَةٍ','بِتَجَاهُلٍ','بِصَوْتٍ عَالٍ'],why:'نَكُونُ سُفَرَاءَ لِبَلَدِنَا، وَنَتْرُكُ انْطِبَاعًا جَيِّدًا عِنْدَ السَّائِحِينَ.'},
  {k:'why',q:'الْحِفَاظُ عَلَى الْمَعَالِمِ التَّارِيخِيَّةِ وَاجِبٌ عَلَى كُلِّ مِصْرِيٍّ.',o:['لِأَنَّهَا تَعْكِسُ هُوِيَّتَنَا، وَتَزِيدُ مِنْ مَكَانَةِ مِصْرَ عَالَمِيًّا','لِأَنَّهَا مِلْكٌ لِلسَّائِحِينَ','لِأَنَّهَا جَدِيدَةٌ'],why:'الْمَعَالِمُ تَعْكِسُ هُوِيَّتَنَا وَتَزِيدُ مِنْ مَكَانَةِ مِصْرَ.'},
  {k:'mcq',q:'كَيْفَ نَرَى الْمَعَالِمَ التَّارِيخِيَّةَ دُونَ أَنْ نَزُورَهَا فِعْلِيًّا؟',o:['بِالزِّيَارَةِ الِافْتِرَاضِيَّةِ عَبْرَ الْإِنْتَرْنِتْ','بِأَخْذِ قِطَعٍ مِنْهَا','لَا يُمْكِنُ أَبَدًا'],why:'بِالْإِنْتَرْنِتْ وَالتِّكْنُولُوجْيَا: زِيَارَةٌ افْتِرَاضِيَّةٌ، وَأَفْلَامٌ وَثَائِقِيَّةٌ، وَصُوَرٌ.'},
  {k:'mcq',q:'بُرْجُ إِيفِل مِنْ مَعَالِمِ ...',o:['فَرَنْسَا','مِصْرَ','فِلَسْطِينَ'],why:'بُرْجُ إِيفِل فِي فَرَنْسَا، وَالْأَهْرَامَاتُ فِي مِصْرَ، وَالْمَسْجِدُ الْأَقْصَى فِي فِلَسْطِينَ.'},
  {k:'odd',q:'هَرَمُ زُوسَرَ - مَعَابِدُ الْكَرْنَكِ - الْجَامِعُ الْأَزْهَرُ - بُرْجُ إِيفِل',o:['بُرْجُ إِيفِل','هَرَمُ زُوسَرَ','الْجَامِعُ الْأَزْهَرُ'],why:'بُرْجُ إِيفِل فِي فَرَنْسَا، وَالْبَاقِي مَعَالِمُ مِصْرِيَّةٌ.'}]};

